if (!root) {
    root = new Node<int>;
    root->value = item;
    root->left = nullptr;
    root->right = nullptr;
    root->bFactor = 0;
} else {
    if (item < root->value) {
        Algorithms::avlInsert(root->left, item);
    } else {
        Algorithms::avlInsert(root->right, item);
    }
    int leftHeight = (root->left) ? 1 + std::max(Algorithms::getHeight(root->left->left), Algorithms::getHeight(root->left->right)) : 0;
    int rightHeight = (root->right) ? 1 + std::max(Algorithms::getHeight(root->right->left), Algorithms::getHeight(root->right->right)) : 0;
    root->bFactor = leftHeight - rightHeight;
    if (root->bFactor > 1) {
        if (item < root->left->value) {
            Algorithms::rotateRight(root);
        } else {
            Algorithms::rotateLeft(root->left);
            Algorithms::rotateRight(root);
        }
    } else if (root->bFactor < -1) {
        if (item > root->right->value) {
            Algorithms::rotateLeft(root);
        } else {
            Algorithms::rotateRight(root->right);
            Algorithms::rotateLeft(root);
        }
    }
}

